class IntrusionText:
    """Player-facing text for prompt injection, shared by the side panel and the catalog so both say the same thing:
a placed tower's live state (hijacked / disabled / blinded), and whether a tower type is immune and why."""
    def __init__(self):
        pass
    @staticmethod
    def tower_line(t):
        """The side-panel line for a placed tower: its current intrusion if it is offline, otherwise its immunity (own or
from a Copilot firewall), or null if it has neither."""
        in_ = t.get_intrusion()
        s = _j.to_int(float(math.ceil(in_.get_remaining())))
        if in_.is_hijacked():
            return _j.cat('HIJACKED ', s, 's: it obeys an injected prompt and fires on your towers')
        if in_.is_disabled():
            return _j.cat('DISABLED ', s, 's: zapped by a hijacked neighbour')
        if in_.is_blinded():
            return _j.cat('BLINDED ', s, "s: swept by Palantir's Panopticon")
        if t.get_stats().injection_immune:
            return _j.cat(IntrusionText.IMMUNE, '  //  ', t.get_stats().injection_immune_reason)
        if in_.is_firewalled():
            return _j.cat(IntrusionText.IMMUNE, '  //  protected by a Copilot firewall')
        return None
    @staticmethod
    def is_warning(t):
        """True if #towerLine describes a problem (the tower is offline) rather than a protection."""
        return t.is_offline()
    @staticmethod
    def type_line(type_):
        """Immunity line for a tower type (shop preview, catalog), or null if the type can be hijacked."""
        why = catalog.injection_immunity_reason(type_)
        return None if (why is None) else _j.cat(IntrusionText.IMMUNE, '  //  ', why)
    @staticmethod
    def firewall_line(type_):
        """Extra line for a type whose aura shields other towers (Copilot's firewall), or null."""
        return 'Firewall: every tower inside its tether radius is immune to prompt injection too.' if catalog.grants_injection_firewall(type_) else None
    @staticmethod
    def vulnerable_line():
        """One line for a type that can be hijacked (catalog), pointing at the counters."""
        return 'Can be hijacked by Prompt Injection enemies (wave 30+) and Palantir. A Copilot firewall nearby protects it.'
    @staticmethod
    def enemy_line(e):
        """Info-panel line for an enemy carrying the Prompt Injection sign, or null."""
        if not e.has(Modifier.INJECTION):
            return None
        return _j.cat('Holds an "', PromptInjection.SIGN, '" sign: every ', _j.to_int(PromptInjection.INTERVAL), ' s it hijacks the ', PromptInjection.MAX_TARGETS, ' nearest towers within ', _j.to_int(PromptInjection.RADIUS), ' px for ', _j.to_int(PromptInjection.HIJACK_TIME), ' s. Stun or Disrupt it to stop the broadcast.')
    @staticmethod
    def state_key(t):
        """Short key of the tower's intrusion state, so a panel can rebuild when it changes."""
        in_ = t.get_intrusion()
        return 'H' if in_.is_hijacked() else ('D' if in_.is_disabled() else ('B' if in_.is_blinded() else ('F' if in_.is_firewalled() else '-')))


